/* Riser Studio design workspace. Kept inline in exported projects for offline use. */
let studioTab='checks',historyKey='',historyStates=[],historyIndex=-1,historyApplying=false,recoveryClock=0,workbookPreview=null;
const studioNumber=(v,fallback=0)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))?Number(v):fallback;
const studioSum=(a,b)=>a.map((n,i)=>n+b[i]);
const studioFactor=v=>Math.max(0,Math.min(1,studioNumber(v,1)));
function loadSource(e){return e.loadBasis|| (state.equipment.some(x=>x.parent===e.id)?'children':'manual')}
function circuitLoads(b){const d=dbScheduleData(b),connected=[0,0,0],demand=[0,0,0];let missing=0,used=0;for(const [way,c] of Object.entries(d.circuits)){if(Number(way)>d.ways||c.status!=='active')continue;used+=c.phases==='3'?3:1;const amps=studioNumber(c.loadA,-1);if(amps<0){missing++;continue}const phases=c.phases==='3'?[0,1,2]:[b.phase==='1'?Math.max(0,['A','B','C'].indexOf(b.loadPhase||'A')):Math.floor((Number(way)-1)/2)%3];for(const p of phases){const kva=amps*(c.phases==='3'?400/Math.sqrt(3):230)/1000;connected[p]+=kva;demand[p]+=kva*studioFactor(c.diversity)}}return {connected,demand,missing,used,spares:d.ways-used}}
function loadSummary(id,visiting=new Set()){const e=state.equipment.find(x=>x.id===id);if(!e||visiting.has(id))return {connected:[0,0,0],demand:[0,0,0],missing:1};const next=new Set(visiting);next.add(id);let connected=[0,0,0],demand=[0,0,0],missing=0,basis=loadSource(e);if(basis==='children'){const kids=state.equipment.filter(x=>x.parent===id);if(!kids.length)missing++;for(const c of kids){const x=loadSummary(c.id,next);connected=studioSum(connected,x.connected);demand=studioSum(demand,x.demand);missing+=x.missing}}else if(basis==='schedule'&&isDistributionBoard(e)){const x=circuitLoads(e);({connected,demand,missing}=x)}else{const amps=studioNumber(e.designLoad,-1);if(amps<0)missing++;else if(e.phase==='1'){const p=['A','B','C'].indexOf(e.loadPhase||'A');connected[Math.max(0,p)]=amps*230/1000;demand=[...connected]}else{connected=Array(3).fill(amps*400/Math.sqrt(3)/1000);demand=[...connected]}}demand=demand.map(n=>n*studioFactor(e.diversity));const total=a=>a.reduce((n,x)=>n+x,0),phaseAmps=demand.map(n=>n*1000/(e.phase==='1'?230:400/Math.sqrt(3)));return {id,basis,connected,demand,connectedKVA:total(connected),demandKVA:total(demand),amps:Math.max(...phaseAmps),phaseAmps,missing,imbalance:Math.max(...phaseAmps)>0?(Math.max(...phaseAmps)-Math.min(...phaseAmps))/Math.max(...phaseAmps)*100:0}}
function coordinateBoardLoads(){for(const e of state.equipment){if(e.useCalculatedDemand&&loadSource(e)!=='manual'){const s=loadSummary(e.id);e.designLoad=s.missing?'':String(Number(s.amps.toFixed(3)))}}}
function designChecks(){const out=[],add=(e,level,message)=>out.push({id:e?.id||'',name:e?.name||'Project',level,message});const refs=new Set();for(const e of state.equipment){if(e.cableRef){if(refs.has(e.cableRef.toUpperCase()))add(e,'error','Duplicate cable reference '+e.cableRef);refs.add(e.cableRef.toUpperCase())}if(!e.name?.trim())add(e,'error','Equipment needs a name');if(!state.levels.some(l=>l.id===e.level))add(e,'error','Assigned level is missing');if(e.parent&&!state.equipment.some(x=>x.id===e.parent))add(e,'error','Upstream equipment is missing');if(!e.parent&&!e.mainSupply&&!['Utility supply','Generator','Solar PV'].includes(e.type))add(e,'warning','No upstream supply selected');const cable=!!e.parent||e.mainSupply&&e.mainSupplyCable!==false;if(cable){if(!(studioNumber(e.cableLength)>0))add(e,'warning','Cable run distance is missing');if(!(studioNumber(e.designLoad)>0))add(e,'warning','Design load is missing or zero');const parent=state.equipment.find(x=>x.id===e.parent),b=breakerParts(e,parent?.type==='Riser cable'?'tapBreaker':'breakerFrom');if(!(studioNumber(b.trip)>0&&studioNumber(b.frame)>0))add(e,'warning','Breaker trip / frame is incomplete');if(studioNumber(b.trip)>studioNumber(b.frame))add(e,'error','Breaker trip exceeds frame');if(studioNumber(e.designLoad)>studioNumber(b.trip)&&studioNumber(b.trip)>0)add(e,'error','Design load exceeds breaker trip');if(e.autoSize&&!e.sizingResult?.ok)add(e,'error','Cable sizing pending: '+(e.sizingResult?.message||'calculate cable'));if(!e.autoSize&&(!e.cable||/TBC|PENDING/i.test(e.cable)))add(e,'warning','Cable size requires selection');if(isFireCable(e)&&!e.autoSize)add(e,'warning','Verify fire cable, supports and system certification')}if(isDistributionBoard(e)){const d=dbScheduleData(e),c=circuitLoads(e);if(c.missing)add(e,'warning',c.missing+' active DB circuits have no load');if(Object.keys(d.circuits).some(n=>Number(n)>d.ways&&d.circuits[n].status==='active'))add(e,'warning','Active circuits are hidden above selected board ways');if(c.used>d.ways)add(e,'error','Circuit allocation exceeds board ways');const summary=loadSummary(e.id),rating=parseFloat(e.rating);if(summary.missing===0&&rating>0&&summary.amps>rating)add(e,'error','Calculated demand exceeds board rating');if(e.phase!=='1'&&summary.imbalance>20&&summary.missing===0)add(e,'warning','Phase imbalance exceeds 20% advisory threshold')}if(e.type==='Main switchboard'){const summary=loadSummary(e.id),rating=parseFloat(e.rating);if(summary.missing===0&&rating>0&&summary.amps>rating)add(e,'error','Calculated demand exceeds MSB rating')}if(e.useCalculatedDemand&&loadSummary(e.id).missing)add(e,'error','Calculated feeder load held pending incomplete downstream loads');if(e.protection){const r=protectionResult(e);r.messages.forEach(m=>add(e,m.startsWith('FAIL')?'error':'warning',m))}}return out.sort((a,b)=>a.level.localeCompare(b.level))}
function studioCommit(){render()}
function setLoadField(id,key,value){const e=state.equipment.find(x=>x.id===id);if(!e)return;const allowed=['loadBasis','loadPhase','diversity','useCalculatedDemand','designLoad'];if(!allowed.includes(key))return;if(key==='diversity'&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>1)){alert('Diversity must be between 0 and 1.');return}e[key]=value;if(key==='useCalculatedDemand'&&value)e.useSupplyRating=false;if(key==='loadBasis'&&value==='manual')e.useCalculatedDemand=false;studioCommit()}
function studioHistory(){const text=JSON.stringify(state);if(historyKey!==projectStorageKey){historyKey=projectStorageKey;historyStates=[text];historyIndex=0;return}if(historyApplying||historyStates[historyIndex]===text)return;historyStates=historyStates.slice(0,historyIndex+1);historyStates.push(text);if(historyStates.length>40)historyStates.shift();historyIndex=historyStates.length-1;try{if(Date.now()-recoveryClock>20000){const key='riser-recovery:'+projectStorageKey,old=JSON.parse(localStorage.getItem(key)||'[]');old.unshift({at:new Date().toISOString(),state:JSON.parse(text)});localStorage.setItem(key,JSON.stringify(old.slice(0,3)));recoveryClock=Date.now()}}catch{}}
function undoProject(){if(historyIndex<1)return;historyApplying=true;state=JSON.parse(historyStates[--historyIndex]);render();historyApplying=false;$('status').textContent='Undid project change'}
function redoProject(){if(historyIndex>=historyStates.length-1)return;historyApplying=true;state=JSON.parse(historyStates[++historyIndex]);render();historyApplying=false;$('status').textContent='Redid project change'}
function recoverProject(index){try{const rows=JSON.parse(localStorage.getItem('riser-recovery:'+projectStorageKey)||'[]'),row=rows[index];if(!row||!confirm('Restore this recovery point? You can undo this.'))return;validateStudioState(row.state);state=structuredClone(row.state);render()}catch(e){alert('Recovery unavailable: '+e.message)}}
function focusDesignItem(id){selected=id;viewMode='diagram';$('studioDialog').close();render();const el=$('diagram').querySelector?.('[data-id="'+CSS.escape(id)+'"]');el?.scrollIntoView?.({block:'center',inline:'center'});el?.focus?.()}
function studioHook(){const move=$('moveEquipmentButton');if(move){move.textContent=state.manualLayout===false?'Move equipment: Off':'Move equipment: On';move.setAttribute?.('aria-pressed',String(state.manualLayout!==false))}studioHistory();const u=$('undoProjectButton'),r=$('redoProjectButton');if(u)u.disabled=historyIndex<1;if(r)r.disabled=historyIndex>=historyStates.length-1;const badge=$('designChecksButton');if(badge)badge.textContent='Design tools · '+designChecks().length+' checks';if($('studioDialog')?.open)renderStudioTools();bindEquipmentDragging()}
function studioTable(headers,rows){return '<div class="studio-table"><table class="ways-table"><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function studioInput(id,label,value,type='text',extra=''){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value??'')}" ${extra}>`}
function studioSelect(id,label,value,choices){return `<label for="${id}">${label}</label><select id="${id}">${choices.map(([k,n])=>`<option value="${esc(k)}" ${String(value)===String(k)?'selected':''}>${esc(n)}</option>`).join('')}</select>`}
function openStudioTools(tab='checks'){studioTab=tab;renderStudioTools();$('studioDialog').showModal();enhanceAccessibility()}
function renderStudioTools(){const tabs=[['checks','Design checks'],['loads','Loads & demand'],['layout','Layout'],['excel','Excel'],['templates','Templates'],['revisions','Revisions'],['sizing','Sizing basis'],['manufacturers','Device presets'],['protection','Protection review'],['recovery','Recovery']];$('studioDialog').innerHTML=`<div class="dialog-heading"><div><h3>Design workspace</h3><p class="hint">Review, coordinate and issue your project.</p></div><button onclick="$('studioDialog').close()" aria-label="Close design workspace">Done</button></div><nav class="studio-tabs" aria-label="Design tools">${tabs.map(([id,label])=>`<button aria-pressed="${studioTab===id}" onclick="studioTab='${id}';renderStudioTools()">${label}</button>`).join('')}</nav><section aria-label="${esc(studioTab)}">${studioPanel()}</section>`;enhanceAccessibility()}
function studioPanel(){if(studioTab==='checks'){const checks=designChecks();return `<h3>${checks.length} items to review</h3><p class="hint">Live completeness and consistency checks. This is not an AS/NZS 3000 compliance certificate.</p><button onclick="exportDesignReport()">Export review report</button>`+studioTable(['Priority','Equipment','Review item'],checks.map(c=>[esc(c.level),`<button onclick="focusDesignItem('${esc(c.id)}')">${esc(c.name)}</button>`,esc(c.message)]))+(checks.length?'':'<p>No completeness or consistency issues found.</p>')}
if(studioTab==='loads')return `<h3>Connected load & maximum demand</h3><p class="hint">230 V single phase / 400 V three phase. Diversity defaults to 1.00. Choose one exclusive load basis to avoid double counting. Downstream demand is summed, then this board’s factor applies; cascaded factors compound. No default statutory diversity is assumed.</p>`+studioTable(['Equipment / basis','Connected kVA','Demand kVA','A / B / C (A)','Diversity','Coordinate feeder'],state.equipment.map(e=>{const s=loadSummary(e.id);return [`<strong>${esc(e.name)}</strong><select aria-label="${esc(e.name)} load basis" onchange="setLoadField('${esc(e.id)}','loadBasis',this.value)">${[['manual','Entered feeder load'],['children','Downstream equipment'],...(isDistributionBoard(e)?[['schedule','DB circuit schedule']]:[])].map(([v,n])=>`<option value="${v}" ${s.basis===v?'selected':''}>${n}</option>`).join('')}</select>${s.basis==='manual'?`<input aria-label="${esc(e.name)} entered current in amperes" type="number" min="0" value="${esc(e.designLoad||'')}" onchange="setLoadField('${esc(e.id)}','designLoad',this.value)">`:''}${e.phase==='1'?`<select aria-label="Supply phase" onchange="setLoadField('${esc(e.id)}','loadPhase',this.value)">${['A','B','C'].map(p=>`<option ${(e.loadPhase||'A')===p?'selected':''}>${p}</option>`).join('')}</select>`:''}`,s.connectedKVA.toFixed(2)+(s.missing?' · incomplete':''),s.missing?'Pending':s.demandKVA.toFixed(2),s.phaseAmps.map(n=>n.toFixed(1)).join(' / '),`<input aria-label="${esc(e.name)} diversity" type="number" min="0" max="1" step=".01" value="${studioFactor(e.diversity)}" onchange="setLoadField('${esc(e.id)}','diversity',this.value)">`,`<label><input type="checkbox" ${e.useCalculatedDemand?'checked':''} ${s.basis==='manual'?'disabled':''} onchange="setLoadField('${esc(e.id)}','useCalculatedDemand',this.checked)"> Use calculated load for feeder sizing</label>${s.missing?esc(s.missing+' missing loads'):esc(s.amps.toFixed(1)+' A maximum phase')}`]}))+sectionLoadPanel();
if(studioTab==='layout')return `<h3>Place equipment precisely</h3><label><input type="checkbox" ${state.manualLayout!==false?'checked':''} onchange="state.manualLayout=this.checked;render()"> Enable drag placement on Diagram and Sheet views</label><p class="hint">Drag an unlocked symbol after closing this panel. Use the visible Move equipment toggle above the drawing. Positions snap to a 20-unit grid; vertical movement stays on its assigned level and expands that level when needed. Moving a DB sideways reroutes its feeder; reset positions to restore automatic vertical alignment. T-off columns move together across levels. Lock items to protect their positions. Automatic routing and crossing jumps remain active; check the resulting routes after manual placement.</p><div class="row"><button onclick="alignEquipmentColumns()">Align selected level’s equipment</button><button onclick="resetLayout()">Reset all positions</button></div>`+studioTable(['Equipment','X offset','Y offset','Lock','Move'],state.equipment.map(e=>[esc(e.name),String(e.layout?.x||0),String(e.layout?.y||0),`<input type="checkbox" aria-label="Lock ${esc(e.name)}" ${e.layout?.locked?'checked':''} onchange="setLayoutLock('${esc(e.id)}',this.checked)">`,`<div class="row">${[['←',-20,0],['→',20,0],['↑',0,-20],['↓',0,20]].map(([n,x,y])=>`<button aria-label="Move ${esc(e.name)} ${n}" onclick="nudgeEquipment('${esc(e.id)}',${x},${y})">${n}</button>`).join('')}</div>`]));
if(studioTab==='excel')return `<h3>Work with Excel</h3><p class="hint">Export an .xlsx workbook containing Equipment, DB Circuits, Cable Schedule and Load Summary. Reimport Equipment and DB Circuits to update by stable IDs; blank IDs add new equipment. Other sheets are reports. Missing rows never delete equipment. Formulas are rejected in editable sheets—paste values first. Keep all column headers.</p><button class="primary" onclick="exportWorkbook()">Export Excel workbook ↓</button><label>Import .xlsx / .csv (max 10 MB)</label><input type="file" accept=".xlsx,.csv" onchange="previewWorkbookFile(event)">${workbookPreview?`<div class="callout">${esc(workbookPreview.message)}</div>${workbookPreview.errors.length?'<ul>'+workbookPreview.errors.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':`<button class="primary" onclick="applyWorkbookPreview()">Apply ${workbookPreview.count} validated rows</button>`}`:''}`;
if(studioTab==='templates'){const saved=studioTemplates();return `<h3>Reusable starting points</h3><p class="hint">Templates create an independent project. Save your current work first. Equipment, levels, title blocks, cable profiles and design settings are retained; revision baselines and recovery history are cleared.</p><div class="row"><button onclick="applyStarterTemplate('commercial')">Commercial starter</button><button onclick="applyStarterTemplate('residential')">Residential starter</button></div>${studioInput('templateName','Template name',state.project)}<button class="primary" onclick="saveStudioTemplate()">Save current project as template</button>`+studioTable(['Saved template','Actions'],saved.map((t,i)=>[esc(t.name),`<button onclick="applyStudioTemplate(${i})">Start new project</button> <button onclick="deleteStudioTemplate(${i})">Delete template</button>`]))+`<button onclick="exportTemplateFile()">Export reusable .risertemplate file</button><label>Import template file</label><input type="file" accept=".risertemplate" onchange="importTemplateFile(event)">`}
if(studioTab==='revisions'){const diff=revisionDiff();return `<h3>Revision comparison</h3><p class="hint">Freeze a baseline before editing an issue. Comparison tracks equipment fields, loads, connections, circuit schedules, levels, profiles, title block and project settings. Added/changed items can be clouded on the schematic; deleted items remain in the register.</p>${studioInput('revisionLabel','Baseline / issue label',state.revisionBaseline?.label||'Revision A')}<button class="primary" onclick="captureBaseline()">Capture current state as baseline</button><label><input type="checkbox" ${state.showRevisionClouds?'checked':''} onchange="state.showRevisionClouds=this.checked;render()"> Show revision clouds on schematic and exports</label><button onclick="exportRevisionRegister()">Export change register</button><p>${state.revisionBaseline?'Baseline: '+esc(state.revisionBaseline.label)+' · '+esc(state.revisionBaseline.at):'No baseline captured yet.'}</p>`+studioTable(['Change','Item','Changed fields'],diff.map(d=>[esc(d.kind),esc(d.name),esc(d.fields.join(', '))]))}
if(studioTab==='sizing'){const e=state.equipment.find(e=>e.id===selected)||cableEquipment()[0];return `<h3>Why this cable size?</h3><select aria-label="Cable to review" onchange="selected=this.value;renderStudioTools()">${cableEquipment().map(x=>`<option value="${esc(x.id)}" ${x.id===e?.id?'selected':''}>${esc(x.cableRef+' · '+x.name)}</option>`).join('')}</select>${e?sizingExplanation(e):'<p>Add a cable first.</p>'}`}
if(studioTab==='manufacturers')return devicePresetPanel();
if(studioTab==='protection')return protectionPanel();
if(studioTab==='recovery'){let entries=[];try{entries=JSON.parse(localStorage.getItem('riser-recovery:'+projectStorageKey)||'[]')}catch{}return `<h3>Undo & recovery</h3><p>Undo history: ${historyIndex} changes available. Redo: ${historyStates.length-historyIndex-1}.</p><div class="row"><button onclick="undoProject()" ${historyIndex<1?'disabled':''}>Undo project change</button><button onclick="redoProject()" ${historyIndex>=historyStates.length-1?'disabled':''}>Redo project change</button></div><p class="hint">Up to 40 changes during this session. Three automatic recovery points for this project are retained on this device, at most once every 20 seconds while editing. Save .riser files for durable backups.</p>`+studioTable(['Recovery point','Project','Action'],entries.map((e,i)=>[esc(e.at),esc(e.state.project),`<button onclick="recoverProject(${i})">Restore recovery point</button>`]))}return ''}
function setLayoutLock(id,locked){const e=state.equipment.find(x=>x.id===id);if(e){e.layout={...e.layout,locked};render()}}
function nudgeEquipment(id,dx,dy){const e=state.equipment.find(x=>x.id===id);if(!e||e.layout?.locked)return;const p=state.equipment.find(x=>x.id===e.parent);let targets=[e];if(p?.type==='Riser cable'){const slot=state.equipment.filter(c=>c.parent===p.id&&c.level===e.level).indexOf(e);targets=state.equipment.filter(c=>c.parent===p.id&&state.equipment.filter(x=>x.parent===p.id&&x.level===c.level).indexOf(c)===slot);if(targets.some(x=>x.layout?.locked))return}for(const t of targets){const old=t.layout||{};t.layout={...old,x:Math.max(-2000,Math.min(10000,Math.round((studioNumber(old.x)+dx)/20)*20)),y:Math.max(-40,Math.min(1000,Math.round((studioNumber(old.y)+(t===e?dy:0))/20)*20))}}render()}
function resetLayout(){if(confirm('Reset all manual positions and locks?')){state.equipment.forEach(e=>delete e.layout);render()}}
function alignEquipmentColumns(){const e=state.equipment.find(x=>x.id===selected);if(!e){alert('Select an equipment item first.');return}state.equipment.filter(x=>x.level===e.level&&!x.layout?.locked).forEach(x=>x.layout={...x.layout,y:0});render()}
function bindEquipmentDragging(){if(state.manualLayout===false||!['diagram','sheet'].includes(viewMode)||!$('diagram').querySelectorAll)return;for(const el of $('diagram').querySelectorAll('[data-id][transform]')){if(el.dataset.diagramLabel&&el.dataset.diagramLabel!=='equipment')continue;const item=state.equipment.find(x=>x.id===el.dataset.id);if(el.style){el.style.touchAction='none';el.style.cursor=item?.layout?.locked?'not-allowed':'grab'}el.onpointerdown=event=>{const e=state.equipment.find(x=>x.id===el.dataset.id);if(!e||e.layout?.locked||event.button!==0)return;const matrix=el.parentElement?.getScreenCTM?.();if(!matrix)return;const inverse=matrix.inverse(),point=ev=>new DOMPoint(ev.clientX,ev.clientY).matrixTransform(inverse),start=point(event),original=el.getAttribute('transform'),base=original.match(/translate\(([-.0-9]+)[ ,]([-.0-9]+)\)/),old=e.layout||{},companions=[...$('diagram').querySelectorAll('[data-id][transform]')].filter(node=>node.dataset.id===e.id&&(!node.dataset.diagramLabel||node.dataset.diagramLabel==='equipment')).map(node=>({node,transform:node.getAttribute('transform')}));if(!companions.some(c=>c.node===el))companions.push({node:el,transform:original});let moved=false;selected=e.id;el.setPointerCapture?.(event.pointerId);if(el.style)el.style.cursor='grabbing';const delta=ev=>{const p=point(ev);return {x:Math.max(-2000,Math.min(10000,Math.round((studioNumber(old.x)+p.x-start.x)/20)*20))-studioNumber(old.x),y:Math.max(-40,Math.min(1000,Math.round((studioNumber(old.y)+p.y-start.y)/20)*20))-studioNumber(old.y)}};let guide=null;const cleanup=()=>{guide?.remove?.();el.onpointermove=null;el.onpointerup=null;el.onpointercancel=null;el.onlostpointercapture=null;if(el.style)el.style.cursor='grab'};el.onpointermove=ev=>{const raw=point(ev);if(Math.hypot(raw.x-start.x,raw.y-start.y)<=5&&!moved)return;moved=true;ev.preventDefault?.();const d=delta(ev);for(const c of companions)c.node.setAttribute('transform',`translate(${d.x},${d.y}) `+c.transform);if(base&&document.createElementNS){if(!guide){guide=document.createElementNS('http://www.w3.org/2000/svg','path');guide.setAttribute('pointer-events','none');guide.setAttribute('stroke','#4169e1');guide.setAttribute('stroke-dasharray','6 6');guide.setAttribute('stroke-width','1');el.parentElement.appendChild(guide)}const x=Number(base[1])+d.x,y=Number(base[2])+d.y;guide.setAttribute('d',`M ${x} 80 V ${y+250} M ${Math.max(0,x-300)} ${y} H ${x+300}`)}};el.onpointerup=ev=>{const d=delta(ev);cleanup();if(!moved)return;ev.preventDefault?.();ev.stopPropagation?.();el.onclick=click=>{click.preventDefault?.();click.stopPropagation?.()};nudgeEquipment(e.id,d.x,d.y);$('status').textContent=e.name+' moved · Undo to restore'};el.onpointercancel=el.onlostpointercapture=()=>{for(const c of companions)c.node.setAttribute('transform',c.transform);cleanup()}}}}
function toggleEquipmentMove(){state.manualLayout=state.manualLayout===false;render()}

function studioTemplates(){try{return JSON.parse(localStorage.getItem('riser-studio-templates')||'[]')}catch{return []}}
function templateState(){const data=structuredClone(state);delete data.revisionBaseline;delete data.showRevisionClouds;return data}
function saveStudioTemplate(){try{const rows=studioTemplates();rows.push({name:$('templateName').value.trim()||state.project,state:templateState()});localStorage.setItem('riser-studio-templates',JSON.stringify(rows.slice(-8)));renderStudioTools()}catch(e){alert('Could not save template: '+e.message)}}
function startTemplate(data){if(!confirm('Start an independent project from this template? Save current work first.'))return;validateStudioState(data);useProjectStorage(makeProjectId());state=structuredClone(data);selected=state.equipment[0]?.id;viewMode='sheet';if(window.riserDesktop)window.riserDesktop.newProject().catch(()=>{});render();setZoom('fit')}
function applyStudioTemplate(i){const row=studioTemplates()[i];if(row)startTemplate(row.state)}
function deleteStudioTemplate(i){if(!confirm('Delete this saved template?'))return;const rows=studioTemplates();rows.splice(i,1);try{localStorage.setItem('riser-studio-templates',JSON.stringify(rows));renderStudioTools()}catch(e){alert(e.message)}}
function applyStarterTemplate(kind){const residential=kind==='residential',levels=[{id:uid(),name:'Level 2'},{id:uid(),name:'Level 1'},{id:uid(),name:'Ground'},{id:uid(),name:'Basement 1'}],source=uid(),msb=uid();const equipment=[{id:source,name:'Utility supply',type:'Utility supply',level:levels[3].id,parent:'',rating:'400 V · 3 phase',cable:'',phase:'3',mainSupply:true},{id:msb,name:'MSB',type:'Main switchboard',level:levels[3].id,parent:source,rating:'TBC',cable:'TBC',phase:'3',splitMetered:residential,fireSafety:true,loadBasis:'children'},...levels.slice(0,3).map((l,i)=>({id:uid(),name:'DB-'+(i+1),type:'Distribution board',level:l.id,parent:msb,rating:'TBC',cable:'TBC',phase:'3',section:residential?'metered':'general',loadBasis:'schedule',dbSchedule:{ways:36,split:!residential,circuits:{}}}))];startTemplate({project:residential?'Residential project':'Commercial project',drawing:'E-001 · REV A',sheetSize:'A1',levels,equipment,nextLevelNumber:3,sizingProfiles:structuredClone(state.sizingProfiles||[]),titleBlock:structuredClone(state.titleBlock||{})})}
function exportTemplateFile(){download((state.project||'Project')+'.risertemplate',JSON.stringify({format:'riser-studio-template',version:1,state:templateState()}),'application/json')}
async function importTemplateFile(event){const f=event.target.files?.[0];if(!f)return;try{if(f.size>5000000)throw Error('Template exceeds 5 MB');const data=JSON.parse(await f.text());if(data.format!=='riser-studio-template'||data.version!==1)throw Error('Invalid template');validateStudioState(data.state);startTemplate(data.state)}catch(e){alert(e.message)}event.target.value=''}
function revisionModel(){const x=structuredClone(state);for(const k of ['revisionBaseline','showRevisionClouds'])delete x[k];x.equipment=x.equipment.map(e=>{for(const k of ['sizingResult','breakerResult'])delete e[k];return e});return x}
function captureBaseline(){if(state.revisionBaseline&&!confirm('Replace the existing comparison baseline?'))return;state.revisionBaseline={label:$('revisionLabel').value.trim()||'Baseline',at:new Date().toISOString(),model:revisionModel()};render()}
function revisionDiff(){if(!state.revisionBaseline?.model)return [];const old=state.revisionBaseline.model,now=revisionModel(),out=[],previous=new Map(old.equipment.map(e=>[e.id,e]));for(const e of now.equipment){const p=previous.get(e.id);if(!p)out.push({id:e.id,name:e.name,kind:'Added',fields:['New equipment']});else{const fields=[...new Set([...Object.keys(p),...Object.keys(e)])].filter(k=>JSON.stringify(p[k])!==JSON.stringify(e[k]));if(fields.length)out.push({id:e.id,name:e.name,kind:'Changed',fields});previous.delete(e.id)}}for(const e of previous.values())out.push({id:e.id,name:e.name,kind:'Deleted',fields:['Removed equipment']});for(const key of new Set([...Object.keys(old),...Object.keys(now)])){if(key==='equipment')continue;if(JSON.stringify(old[key])!==JSON.stringify(now[key]))out.push({id:'',name:'Project',kind:'Changed',fields:[key]})}return out}
function revisionCloudSVG(positions,boardWidth){if(!state.showRevisionClouds)return '';return revisionDiff().filter(d=>d.id&&d.kind!=='Deleted').map(d=>{const e=state.equipment.find(x=>x.id===d.id),p=positions.get(d.id);if(!e||!p)return '';const x=p.x-(e.type==='Main switchboard'?boardWidth(e)/2+15:30),y=p.y-60,w=e.type==='Main switchboard'?boardWidth(e)+30:270,h=e.type==='Main switchboard'?225:125;let path=`M ${x} ${y}`;for(let n=0;n<Math.ceil(w/24);n++)path+=` q 12 -10 24 0`;path+=` V ${y+h}`;for(let n=0;n<Math.ceil(w/24);n++)path+=' q -12 10 -24 0';path+=' Z';return `<g data-revision-cloud="${esc(d.id)}"><path d="${path}" fill="none" stroke="#b92d36" stroke-width="1.4"/><text x="${x}" y="${y-9}" font-size="10" fill="#b92d36">${esc(state.revisionBaseline.label)} · ${esc(d.kind)}</text></g>`}).join('')}
function exportRevisionRegister(){const rows=revisionDiff();download('Revision-register.txt',['Baseline: '+(state.revisionBaseline?.label||'None'),...rows.map(d=>[d.kind,d.name,d.fields.join(', ')].join('\t'))].join('\n'),'text/plain')}
function sizingExplanation(e){const result=cableSizing(e),profile=(state.sizingProfiles||[]).find(p=>p.id===e.sizingProfile);if(!profile)return '<div class="callout">Choose a cable profile in Equipment properties first.</div>';const load=studioNumber(e.designLoad),length=studioNumber(e.cableLength),factor=studioNumber(e.correctionFactor),voltage=e.phase==='1'?230:400,trip=studioNumber(e[state.equipment.find(x=>x.id===e.parent)?.type==='Riser cable'?'tapBreakerTrip':'breakerFromTrip']);const rows=profile.rows.slice().sort((a,b)=>a.size-b.size),capacity=rows.find(r=>r.amps*factor>=trip),drop=rows.find(r=>r.mv*load*length/1000/voltage*100<=studioNumber(e.voltageDrop)),governing=capacity&&drop?capacity.size>drop.size?'Current-carrying capacity':drop.size>capacity.size?'Voltage drop':'Both criteria':'Pending';return `<div class="callout">${esc(result.message)}<br>Governing constraint: ${governing}</div><p class="hint">Capacity = tabulated amps × combined correction factor. Voltage drop = table mV/A/m × design A × route metres ÷ 1000. The profile’s phase-specific coefficient already includes its phase factor. No further √3 is applied.</p><p>Load ${load} A · breaker ${trip} A · length ${length} m · factor ${factor} · limit ${esc(e.voltageDrop||'TBC')}%</p><p>Profile: ${esc(profile.name)}<br>Source: ${esc(profile.source||profile.reference||'See catalogue profile reference')}<br>Conditions: ${esc(profile.conditions||profile.notes||'Review source installation and derating conditions')}</p>`+studioTable(['mm²','Table A','Corrected A','Drop V','Drop %','Result'],rows.map(r=>{const pct=r.mv*load*length/1000/voltage*100;return [String(r.size),String(r.amps),(r.amps*factor).toFixed(1),(r.mv*load*length/1000).toFixed(2),pct.toFixed(2),result.ok&&r.size===result.size?'SELECTED':r.amps*factor<trip?'Capacity too low':pct>studioNumber(e.voltageDrop)?'Drop too high':'Meets numeric limits']}))}
