function allDevicePresets(){return [...verifiedDevicePresets,...(state.devicePresets||[])]}
function devicePresetPanel(){const board=elevationBoard(),ways=board?elevationLayout(board).ways:[];return `<h3>Manufacturer device presets</h3><p class="hint">72 manufacturer-published Schneider Electric and ABB fixed-device presets are preloaded. Select the exact family, frame range and pole count; dimensions and available Icu at 415 V transfer automatically. Legacy entries are identified. No manual data entry is needed for these devices. Fixed 600 mm compartments, busbar zones and cable zones remain your project rules. Body dimensions do not account for accessories, bending radii or assembly verification.</p>`+studioSelect('presetBoard','Switchboard',board?.id,state.equipment.filter(e=>e.type==='Main switchboard').map(e=>[e.id,e.name]))+`<button onclick="state.elevationBoardId=$('presetBoard').value;render();">Select board</button>`+studioTable(['Way','Current envelope / mm','Apply preset'],ways.map(w=>[esc(w.name),esc(w.env.w+' × '+w.env.h+' × '+w.env.d),`<select id="device-${esc(w.id)}" aria-label="Preset for ${esc(w.name)}"><option value="">Choose preset</option>${allDevicePresets().filter(p=>w.frame>studioNumber(p.minFrame)&&w.frame<=p.maxFrame&&w.poles===p.poles).map(p=>`<option value="${esc(p.id)}">${esc(p.manufacturer+' · '+p.model)}</option>`).join('')}</select><button onclick="applyDevicePreset('${esc(board.id)}','${esc(w.id)}',$('device-${esc(w.id)}').value)">Apply to elevation</button>`]))+`<details><summary>Optional project-specific device override</summary><h3>Add a verified device</h3><div class="title-grid">${studioInput('deviceMaker','Manufacturer','')}${studioInput('deviceModel','Model / mounting','')}${studioInput('deviceFrame','Maximum frame A','', 'number')}${studioSelect('devicePoles','Poles',3,[[3,'3P'],[4,'4P']])}${studioInput('deviceWidth','Body width mm','','number')}${studioInput('deviceHeight','Body height mm','','number')}${studioInput('deviceDepth','Body depth mm','','number')}${studioInput('deviceSource','Drawing reference / source URL','')}</div><button class="primary" onclick="saveDevicePreset()">Save device preset</button></details>`+studioTable(['Manufacturer / model','Envelope','Icu at 415 V','Reference'],allDevicePresets().map(p=>[esc(p.manufacturer+' · '+p.model),esc(p.width+' × '+p.height+' × '+p.depth+' mm'),p.icuKA?esc(p.icuKA+' kA'):'Body data only',esc((p.reference||'')+(p.legacy?' · LEGACY':''))+(/^https:\/\//.test(p.source)?`<br><a href="${esc(p.source)}" target="_blank" rel="noopener">Manufacturer source ↗</a>`:'<br>'+esc(p.source))]))}
function saveDevicePreset(){try{const p={id:uid(),manufacturer:$('deviceMaker').value.trim(),model:$('deviceModel').value.trim(),maxFrame:Number($('deviceFrame').value),poles:Number($('devicePoles').value),width:Number($('deviceWidth').value),height:Number($('deviceHeight').value),depth:Number($('deviceDepth').value),source:$('deviceSource').value.trim()};validateDevicePreset(p);(state.devicePresets??=[]).push(p);render()}catch(e){alert(e.message)}}
function validateDevicePreset(p){if(!p||['id','manufacturer','model','source'].some(k=>typeof p[k]!=='string'||!p[k].trim()||p[k].length>500)||![3,4].includes(p.poles)||['maxFrame','width','height','depth'].some(k=>!Number.isFinite(p[k])||p[k]<=0||p[k]>10000))throw Error('Enter manufacturer, model, reference and positive verified dimensions/frame.')}
function applyDevicePreset(boardId,wayId,presetId){const b=state.equipment.find(e=>e.id===boardId),p=allDevicePresets().find(x=>x.id===presetId),way=b&&elevationLayout(b).ways.find(w=>w.id===wayId);if(!b||!p||!way||way.frame<=studioNumber(p.minFrame)||way.frame>p.maxFrame||way.poles!==p.poles){alert('Preset does not match this way frame and poles.');return}b.elevationWays??={};b.elevationWays[wayId]={...b.elevationWays[wayId],width:p.width,height:p.height,depth:p.depth,poles:p.poles,devicePreset:p.id,manufacturer:p.manufacturer,model:p.model,source:p.source};if(p.icuKA){const target=wayId==='incoming'?b:state.equipment.find(e=>e.id===wayId);if(target)target.protection={...target.protection,devicePreset:p.id,icuKA:String(p.icuKA),reference:p.reference+' · '+p.source,deviceVoltage:'415'}}render()}
function protectionResult(e){const p=e.protection||{},messages=[];const positive=k=>studioNumber(p[k])>0;let breaking='Pending data',earth='Pending data',adiabatic='Pending data',discrimination='Pending verified curves';if(positive('faultKA')&&positive('icuKA')){breaking=Number(p.icuKA)>=Number(p.faultKA)?'Numeric breaking-capacity check passes':'FAIL: breaking capacity below prospective fault';if(breaking.startsWith('FAIL'))messages.push(breaking)}if(positive('zs')&&positive('ia')&&positive('u0')){earth=Number(p.zs)*Number(p.ia)<=Number(p.u0)?'Numeric Zs × Ia ≤ U0 check passes':'FAIL: Zs × Ia exceeds U0';if(earth.startsWith('FAIL'))messages.push(earth)}if(['faultKA','clearingTime','earthSize','k'].every(positive)){const required=(Number(p.faultKA)*1000)**2*Number(p.clearingTime),available=(Number(p.k)*Number(p.earthSize))**2;adiabatic=available>=required?'Numeric adiabatic k²S² ≥ I²t check passes':'FAIL: earth conductor adiabatic capacity exceeded';if(adiabatic.startsWith('FAIL'))messages.push(adiabatic)}if(!p.reference)messages.push('Protection study needs device/source references');if(!positive('faultKA')||!positive('icuKA'))messages.push('Fault level / breaking capacity pending');const curve=(v)=>String(v||'').trim().split(/\n/).filter(Boolean).map(l=>l.split(',').map(Number));const down=curve(p.downCurve),up=curve(p.upCurve);if(down.length>=2&&up.length>=2){const valid=c=>c.every((r,i)=>r.length===3&&r.every(n=>Number.isFinite(n)&&n>0)&&r[1]<=r[2]&&(!i||r[0]>c[i-1][0]));if(!valid(down)||!valid(up))discrimination='Invalid curve data';else{const sample=[...new Set([...down,...up].map(r=>r[0]))].filter(i=>i>=Math.max(down[0][0],up[0][0])&&i<=Math.min(down.at(-1)[0],up.at(-1)[0]));const interp=(c,i,col)=>{let n=c.findIndex(r=>r[0]>=i);if(n<=0)return c[0][col];const a=c[n-1],b=c[n],t=Math.log(i/a[0])/Math.log(b[0]/a[0]);return Math.exp(Math.log(a[col])+t*Math.log(b[col]/a[col]))};if(sample.length){const pass=sample.every(i=>interp(down,i,2)<interp(up,i,1));discrimination=pass?'Curves separated over shared current range only':'FAIL: time-current bands overlap';if(!pass)messages.push(discrimination)}}}return {breaking,earth,adiabatic,discrimination,messages}}
function protectionPanel(){const e=state.equipment.find(x=>x.id===selected)||state.equipment[0];if(!e)return '<p>Add equipment first.</p>';const p=e.protection||{},r=protectionResult(e);return `<h3>Fault & protection review</h3><p class="hint">Engineering worksheet using supplied study results and verified manufacturer data. It does not calculate a network fault level, certify disconnection time, or establish energy selectivity/cascading. Ia must be selected for the required disconnection time. Curve separation is limited to the entered common range and excludes current-limiting energy behaviour.</p>`+studioSelect('protectionEquipment','Equipment',e.id,state.equipment.map(e=>[e.id,e.name]))+`<button onclick="selected=$('protectionEquipment').value;renderStudioTools()">Select equipment</button>${studioSelect('protectionPreset','Published device data',p.devicePreset||'',[['','Select manufacturer model'],...verifiedDevicePresets.filter(d=>d.icuKA).map(d=>[d.id,d.manufacturer+' · '+d.model+' · '+d.icuKA+' kA / 415 V'])])}<button onclick="applyProtectionPreset('${esc(e.id)}',$('protectionPreset').value)">Use published breaking capacity</button><div class="title-grid">${[['faultKA','Prospective fault current (kA)'],['icuKA','Device breaking capacity Icu (kA)'],['zs','Earth-fault loop impedance Zs (Ω)'],['ia','Operating current Ia at required time (A)'],['u0','Phase-to-earth voltage U0 (V)'],['clearingTime','Maximum clearing time at fault (s)'],['earthSize','Earth conductor area S (mm²)'],['k','Verified adiabatic k value']].map(([k,n])=>studioInput('prot-'+k,n,p[k],'number','min="0" step="any"')).join('')}${studioInput('prot-reference','Study / device / k reference',p.reference)}</div><label>Downstream curve: current A, minimum seconds, maximum seconds (one point per line)</label><textarea id="prot-downCurve" rows="4">${esc(p.downCurve||'')}</textarea><label>Upstream curve: current A, minimum seconds, maximum seconds</label><textarea id="prot-upCurve" rows="4">${esc(p.upCurve||'')}</textarea><button class="primary" onclick="saveProtection('${esc(e.id)}')">Calculate supplied-data checks</button>`+studioTable(['Check','Result'],[['Breaking capacity',r.breaking],['Earth loop',r.earth],['Adiabatic earth conductor',r.adiabatic],['Time-current separation',r.discrimination]].map(a=>a.map(esc)))}
function saveProtection(id){const e=state.equipment.find(x=>x.id===id);if(!e)return;const p={...e.protection};for(const k of ['faultKA','icuKA','zs','ia','u0','clearingTime','earthSize','k','reference','downCurve','upCurve'])p[k]=$('prot-'+k).value.trim();for(const k of ['faultKA','icuKA','zs','ia','u0','clearingTime','earthSize','k'])if(p[k]!==''&&(!(Number(p[k])>0)||!Number.isFinite(Number(p[k])))){alert('Protection inputs must be positive numbers or blank.');return}e.protection=p;render()}
function exportDesignReport(){const text=['Riser Studio design review — '+state.project,new Date().toISOString(),'Checks',...designChecks().map(c=>[c.level,c.name,c.message].join('\t')),'','Load summary (incomplete loads remain pending)',...state.equipment.map(e=>{const s=loadSummary(e.id);return [e.name,s.basis,s.connectedKVA.toFixed(2)+' kVA connected',s.missing?'Pending':s.demandKVA.toFixed(2)+' kVA demand',s.phaseAmps.map(n=>n.toFixed(1)).join('/')+' A'].join('\t')})].join('\n');download('Design-review.txt',text,'text/plain')}
const workbookFields=['id','name','type','level','parent','rating','phase','designLoad','cableRef','cable','cableRating','cableLength','installation','voltageDrop','correctionFactor','sizingProfile','cableTemperature','profileFamily','breakerFromTrip','breakerFromFrame','section','loadBasis','loadPhase','diversity','useCalculatedDemand'];
const circuitWorkbookFields=['boardId','way','description','cableSize','breaker','phases','status','loadA','diversity'];
function equipmentWorkbookRows(){return state.equipment.map(e=>Object.fromEntries(workbookFields.map(k=>[k,k==='level'?(state.levels.find(l=>l.id===e.level)?.name||''):k==='diversity'?studioFactor(e[k]):k==='useCalculatedDemand'?!!e[k]:e[k]??''])))}
function workbookData(){return {Equipment:equipmentWorkbookRows(),'DB Circuits':state.equipment.filter(isDistributionBoard).flatMap(b=>Object.entries(dbScheduleData(b).circuits).map(([way,c])=>({boardId:b.id,way:Number(way),...c}))), 'Cable Schedule':cableRows(),'Load Summary':state.equipment.map(e=>{const s=loadSummary(e.id);return {id:e.id,name:e.name,basis:s.basis,connectedKVA:s.connectedKVA,demandKVA:s.missing?'Pending':s.demandKVA,phaseA:s.phaseAmps[0],phaseB:s.phaseAmps[1],phaseC:s.phaseAmps[2],missingLoads:s.missing}}),Instructions:[{note:'Equipment updates by id. Blank id adds new item. Parent uses id. Level uses level name. Missing rows do not delete. DB Circuits updates by boardId and way. Reports are not imported. Formulas must be pasted as values.'}]}}
async function exportWorkbook(){try{const wb=XLSX.utils.book_new(),data=workbookData();for(const [name,rows] of Object.entries(data)){const ws=XLSX.utils.json_to_sheet(rows,{header:name==='Equipment'?workbookFields:name==='DB Circuits'?circuitWorkbookFields:undefined});ws['!cols']=(name==='Equipment'?workbookFields:circuitWorkbookFields).map(k=>({wch:['name','cable','description'].includes(k)?32:20}));XLSX.utils.book_append_sheet(wb,ws,name)}const bytes=XLSX.write(wb,{bookType:'xlsx',type:'array'});await downloadBinary('Riser-Studio-workbook.xlsx',new Uint8Array(bytes))}catch(e){alert('Excel export failed: '+e.message)}}
async function downloadBinary(name,bytes){if(window.riserDesktop){let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return window.riserDesktop.exportFile({name,content:btoa(binary),encoding:'base64'})}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validateWorkbookRows(equipmentRows,circuitRows=[]){const next=structuredClone(state),errors=[],seen=new Set(),boardSeen=new Set();let count=0;try{if(equipmentRows.length>2000||circuitRows.length>10000)throw Error('Workbook row limit exceeded');for(let index=0;index<equipmentRows.length;index++){const row=equipmentRows[index];if(!Object.values(row).some(v=>String(v).trim()))continue;count++;const id=String(row.id||'').trim()||uid();if(seen.has(id))throw Error('Duplicate equipment id at row '+(index+2));seen.add(id);let e=next.equipment.find(x=>x.id===id);if(!e){e={id,name:'',type:'Distribution board',level:next.levels[0].id,parent:'',rating:'TBC',cable:'',phase:'3'};next.equipment.push(e)}for(const k of workbookFields){if(!Object.hasOwn(row,k)||k==='id')continue;const value=String(row[k]??'').trim();if(k==='level'){const l=next.levels.find(l=>l.name===value||l.id===value);if(!l)throw Error('Unknown level at row '+(index+2)+': '+value);e.level=l.id}else if(k==='useCalculatedDemand'){if(!['true','false','1','0','TRUE','FALSE',''].includes(value))throw Error('Invalid useCalculatedDemand at row '+(index+2));e[k]=['true','TRUE','1'].includes(value)}else if(k==='diversity'){if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>1))throw Error('Invalid diversity at row '+(index+2));e[k]=value===''?1:Number(value)}else if(k==='loadBasis'){if(value&&!['manual','children','schedule'].includes(value))throw Error('Invalid load basis');if(value)e[k]=value;else delete e[k]}else if(k==='loadPhase'){if(value&&!['A','B','C'].includes(value))throw Error('Invalid supply phase');if(value)e[k]=value}else e[k]=value}if(e.mainSupply&&e.parent)throw Error('Main supply cannot have an upstream parent: '+e.name)}for(const row of circuitRows){if(!Object.values(row).some(v=>String(v).trim()))continue;count++;const b=next.equipment.find(e=>e.id===String(row.boardId));if(!b||!isDistributionBoard(b))throw Error('Unknown distribution board '+row.boardId);const way=Number(row.way),key=b.id+':'+way;if(boardSeen.has(key))throw Error('Duplicate circuit '+key);boardSeen.add(key);b.dbSchedule=structuredClone(dbScheduleData(b));b.dbSchedule.circuits[way]=Object.fromEntries(circuitWorkbookFields.filter(k=>!['boardId','way'].includes(k)).map(k=>[k,String(row[k]??'')]));const c=b.dbSchedule.circuits[way];c.phases=c.phases||'1';c.status=c.status||'blank';if(c.diversity==='')delete c.diversity;else c.diversity=Number(c.diversity);validateDBSchedule(b)}validateStudioState(next)}catch(e){errors.push(e.message)}return {sourceState:JSON.stringify(state),sourceProject:projectStorageKey,next,errors,count,message:errors.length?'Import blocked. No project changes have been applied.':count+' rows validated. Existing IDs update; blank IDs add equipment. Review your workbook before applying.'}}
async function previewWorkbookFile(event){const f=event.target.files?.[0];if(!f)return;try{if(f.size>10000000)throw Error('Workbook exceeds 10 MB');const wb=XLSX.read(await f.arrayBuffer(),{type:'array',cellFormula:true,cellDates:false}),sheet=wb.Sheets.Equipment||wb.Sheets[wb.SheetNames[0]],circuits=wb.Sheets['DB Circuits'];if(!sheet)throw Error('No equipment sheet found');for(const ws of [sheet,circuits].filter(Boolean))for(const key of Object.keys(ws)){if(ws[key]?.f)throw Error('Formula found in editable sheet at '+key+'. Paste values first.')}const header=XLSX.utils.sheet_to_json(sheet,{header:1,defval:''})[0]||[];if(!['id','name','type','level','parent'].every(k=>header.includes(k)))throw Error('Equipment headers missing. Start with an exported workbook.');workbookPreview=validateWorkbookRows(XLSX.utils.sheet_to_json(sheet,{defval:''}),circuits?XLSX.utils.sheet_to_json(circuits,{defval:''}):[])}catch(e){workbookPreview={errors:[e.message],message:'Import blocked; project unchanged',count:0}}renderStudioTools()}
function applyWorkbookPreview(){if(!workbookPreview||workbookPreview.errors.length)return;if(workbookPreview.sourceProject!==projectStorageKey||workbookPreview.sourceState!==JSON.stringify(state)){alert('The project changed after preview. Import the workbook again to avoid overwriting newer work.');workbookPreview=null;renderStudioTools();return}if(!confirm('Apply '+workbookPreview.count+' validated spreadsheet rows? This can be undone.'))return;state=workbookPreview.next;workbookPreview=null;render()}
function validateStudioState(data){if(!data||typeof data.project!=='string'||typeof data.drawing!=='string'||!Array.isArray(data.levels)||!data.levels.length||!Array.isArray(data.equipment)||data.equipment.length>2000)throw Error('Invalid project data');const ids=new Set(data.equipment.map(e=>e.id));if(ids.size!==data.equipment.length)throw Error('Duplicate equipment IDs');if(new Set(data.levels.map(l=>l.id)).size!==data.levels.length)throw Error('Duplicate level IDs');const refs=new Set();for(const l of data.levels)if(typeof l.id!=='string'||typeof l.name!=='string')throw Error('Invalid level');for(const e of data.equipment){if(!/^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$/.test(e.id)||['constructor','prototype'].includes(e.id))throw Error('Equipment IDs must use letters, digits, hyphens or underscores');if(['id','name','type','level','parent','rating','cable'].some(k=>typeof e[k]!=='string'||e[k].length>500)||!types.includes(e.type)||!data.levels.some(l=>l.id===e.level))throw Error('Invalid equipment '+e.name);if(e.parent&&!ids.has(e.parent))throw Error('Missing upstream equipment '+e.parent);let p=e.parent,seen=new Set([e.id]);while(p){if(seen.has(p))throw Error('Circular supply connection');seen.add(p);p=data.equipment.find(x=>x.id===p)?.parent}if(e.phase!==undefined&&!['1','3'].includes(e.phase))throw Error('Invalid equipment phase');for(const k of ['designLoad','cableLength','correctionFactor','voltageDrop'])if(e[k]!==undefined&&e[k]!==''&&(!Number.isFinite(Number(e[k]))||Number(e[k])<0))throw Error('Invalid '+k+' for '+e.name);for(const k of ['breakerFromTrip','breakerFromFrame','tapBreakerTrip','tapBreakerFrame'])if(e[k]!==undefined&&e[k]!==''&&!/^[1-9]\d*$/.test(e[k]))throw Error('Invalid breaker rating');if(e.cableRef){const key=e.cableRef.toUpperCase();if(refs.has(key))throw Error('Duplicate cable reference '+key);refs.add(key)}if(e.protection){if(typeof e.protection!=='object'||Array.isArray(e.protection)||Object.values(e.protection).some(v=>typeof v!=='string'||v.length>20000))throw Error('Invalid protection worksheet')}if(e.useCalculatedDemand!==undefined&&typeof e.useCalculatedDemand!=='boolean')throw Error('Invalid calculated demand option');if(e.loadBasis!==undefined&&!['manual','children','schedule'].includes(e.loadBasis))throw Error('Invalid load basis');if(e.loadPhase!==undefined&&!['A','B','C'].includes(e.loadPhase))throw Error('Invalid load phase');if(e.diversity!==undefined&&(!Number.isFinite(Number(e.diversity))||Number(e.diversity)<0||Number(e.diversity)>1))throw Error('Invalid diversity');if(e.layout&&(['x','y'].some(k=>!Number.isFinite(e.layout[k])||Math.abs(e.layout[k])>10000)||typeof e.layout.locked!=='boolean'&&e.layout.locked!==undefined))throw Error('Invalid layout');validateDBSchedule(e);validateElevationData(e);for(const c of Object.values(e.dbSchedule?.circuits||{})){if(c.loadA!==undefined&&c.loadA!==''&&(!Number.isFinite(Number(c.loadA))||Number(c.loadA)<0))throw Error('Invalid circuit load');if(c.diversity!==undefined&&(!Number.isFinite(Number(c.diversity))||Number(c.diversity)<0||Number(c.diversity)>1))throw Error('Invalid circuit diversity')}}if(data.devicePresets!==undefined){if(!Array.isArray(data.devicePresets)||data.devicePresets.length>200)throw Error('Invalid device presets');data.devicePresets.forEach(validateDevicePreset)}validateSizingProfiles(data.sizingProfiles||[]);if(data.revisionBaseline&&(!data.revisionBaseline.model||!Array.isArray(data.revisionBaseline.model.equipment)||typeof data.revisionBaseline.label!=='string'))throw Error('Invalid revision baseline')}
function saveCircuitLoad(){const b=dbScheduleBoard();if(!b)return;const d=dbScheduleData(b),hit=dbCircuitAt(d,dbSelectedWay),c=d.circuits[hit.way];if(!c||c.status!=='active'){alert('Save an active circuit first.');return}const load=$('dbCircuitLoadA').value,div=$('dbCircuitDiversity').value;if(load!==''&&(!Number.isFinite(Number(load))||Number(load)<0)||!Number.isFinite(Number(div))||Number(div)<0||Number(div)>1){alert('Enter a non-negative load and diversity from 0 to 1.');return}c.loadA=load;c.diversity=Number(div);b.dbSchedule=d;render()}
function circuitLoadFields(b){const d=dbScheduleData(b),hit=dbCircuitAt(d,dbSelectedWay),c=hit.c,s=circuitLoads(b);return `<div class="divider"></div><h3>Circuit load coordination</h3>${studioInput('dbCircuitLoadA','Design current A per phase (not breaker rating)',c.loadA||'','number','min="0" step="any"')}${studioInput('dbCircuitDiversity','Circuit diversity / coincidence factor',c.diversity??1,'number','min="0" max="1" step=".01"')}<button class="primary action-wide" onclick="saveCircuitLoad()">Save circuit load</button><p class="hint">${s.used} active ways / ${d.ways}; ${s.spares} inactive or spare ways. ${s.missing} active circuits need loads. Phase balance follows the schedule’s A/B/C row allocation.</p><button class="action-wide" onclick="openStudioTools('loads')">Review board load and phase balance →</button>`}

function sectionLoadSummaries(board){return sections(board).map(z=>{const children=state.equipment.filter(e=>e.parent===board.id&&feederSection(e,board)===z.id);let connected=[0,0,0],demand=[0,0,0],missing=0;for(const e of children){const v=loadSummary(e.id);connected=studioSum(connected,v.connected);demand=studioSum(demand,v.demand);missing+=v.missing}demand=demand.map(v=>v*studioFactor(board.diversity));return {board:board.name,section:z.name,connectedKVA:connected.reduce((a,b)=>a+b,0),demandKVA:demand.reduce((a,b)=>a+b,0),phaseAmps:demand.map(v=>v*1000/(400/Math.sqrt(3))),missing}})}
function sectionLoadPanel(){const rows=state.equipment.filter(e=>e.type==='Main switchboard').flatMap(sectionLoadSummaries);return '<h3>MSB section demand</h3><p class="hint">Sections aggregate their actual outgoing feeders, independently of a manually entered incoming load. The board diversity factor applies to each section.</p>'+studioTable(['Board','Section','Connected kVA','Demand kVA','A / B / C (A)'],rows.map(r=>[esc(r.board),esc(r.section),r.connectedKVA.toFixed(2),r.missing?'Pending':r.demandKVA.toFixed(2),r.phaseAmps.map(n=>n.toFixed(1)).join(' / ')]))}

function applyProtectionPreset(id,presetId){const e=state.equipment.find(e=>e.id===id),p=verifiedDevicePresets.find(p=>p.id===presetId);if(!e||!p?.icuKA)return;const trip=studioNumber(breakerParts(e,'breakerFrom').frame);if(trip&&!(trip>studioNumber(p.minFrame)&&trip<=p.maxFrame)){alert('Device family does not cover this frame rating.');return}e.protection={...e.protection,devicePreset:p.id,icuKA:String(p.icuKA),deviceVoltage:'415',reference:p.reference+' · '+p.source};render()}
